def bboxes(g,bg):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and not seen[r][c]:
                col=g[r][c]; cells=[]; stack=[(r,c)]
                while stack:
                    y,x=stack.pop()
                    if seen[y][x] or g[y][x]!=col: continue
                    seen[y][x]=True; cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==col:
                            stack.append((ny,nx))
                out.append((col,min(p[0]for p in cells),min(p[1]for p in cells),max(p[0]for p in cells),max(p[1]for p in cells)))
    return out
