import os,re,json
from collections import Counter,defaultdict

def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def comps(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    cnt=Counter(x for row in g for x in row); bg=min(cnt.most_common(1)[0][0], max(cnt.keys()))
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and not seen[r][c]:
                col=g[r][c]; stack=[(r,c)]; cells=[]
                while stack:
                    y,x=stack.pop(); seen[y][x]=True
                    if g[y][x]!=col: continue
                    cells.append((y,x))
                    for dy,dx in ((-1,0),(1,0),(0,-1),(0,1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==col:
                            stack.append((ny,nx))
                pat=sorted((p[0]-min(p[0] for p in cells),p[1]-min(p[1] for p in cells)) for p in cells)
                out.append({'col':col,'sz':len(cells),'shape':tuple(pat),'box':(min(p[0] for p in cells),min(p[1] for p in cells)),
                           'bbh':max(p[0] for p in cells)-min(p[0] for p in cells)+1,'bbw':max(p[1] for p in cells)-min(p[1] for p in cells)+1})
    return out

for i in (1,2,3,4):
    cin=comps(G[f'Demo pair {i} input']); cout=comps(G[f'Demo pair {i} output'])
    changed=[(a,b) for a,b in zip(cin,cout) if a!=b]
